  const cancel=()=>{
   // Cancel synchronously before rejecting; an untrusted cancel callback must
   // not delay release of a worker request slot.
   reader.cancel().catch(()=>{});rejectAbort(Error('WORKER_REQUEST_TIMEOUT'));
