 return req=>{
  if(remaining>0){
   remaining--;
   try{observe(Object.freeze({kind:'wave5_ingress_v4',worker,...classifyEdgeIngress(req.url,endpointUrl,allowedRoutes)}));}catch{}
  }
  return handler(req);
 };
